from pathlib import Path

# wordpress-auth.js
p=Path('api/wordpress-auth.js'); s=p.read_text()
helper='''export async function uploadUserMedia(imageBuffer, filename, mimeType) {\n  try {\n    const response = await axios.post(`${WORDPRESS_API}/wp/v2/media`, imageBuffer, {\n      headers: { ...getAdminAuthHeader(), 'Content-Type': mimeType, 'Content-Disposition': `attachment; filename="${filename}"` },\n      maxBodyLength: 50 * 1024 * 1024, timeout: 30000,\n    });\n    const url = response.data?.source_url;\n    if (!url) return { success: false, error: 'Upload succeeded but no URL was returned' };\n    return { success: true, url, mediaId: response.data.id };\n  } catch (error) {\n    console.error('User media upload failed:', error.response?.data || error.message);\n    return { success: false, error: error.response?.data?.message || error.message };\n  }\n}\n\n'''
if 'export async function uploadUserMedia' not in s: s=s.replace('export async function uploadProfilePicture',helper+'export async function uploadProfilePicture')
s=s.replace('  uploadProfilePicture,\n};','  uploadProfilePicture,\n  uploadUserMedia,\n};')
p.write_text(s)

# server-wordpress.js
p=Path('api/server-wordpress.js'); s=p.read_text()
s=s.replace('  uploadProfilePicture,\n} from \'./wordpress-auth.js\';','  uploadProfilePicture,\n  uploadUserMedia,\n} from \'./wordpress-auth.js\';')
marker='// ========== Settings / API Keys / Profile Endpoints =========='
block='''// ========== Cloud Sessions / Persistent Papers ==========\n\napp.get('/api/sessions', authMiddleware, async (req, res) => {\n  try {\n    const sessions = (await getUserMeta(req.user.id, 'redpen_sessions')) || [];\n    res.json({ sessions: Array.isArray(sessions) ? sessions : [] });\n  } catch (error) { res.status(500).json({ message: 'Failed to load sessions' }); }\n});\n\napp.post('/api/sessions', authMiddleware, async (req, res) => {\n  try {\n    const session = req.body?.session;\n    if (!session?.courseCode) return res.status(400).json({ message: 'courseCode is required' });\n    const existing = (await getUserMeta(req.user.id, 'redpen_sessions')) || [];\n    const sessions = Array.isArray(existing) ? existing : [];\n    const key = s => `${s.courseCode}|${s.academicYear || ''}|${s.semester || ''}|${s.sessionLabel || ''}|${s.customName || ''}`;\n    const updated = [session, ...sessions.filter(s => key(s) !== key(session))].slice(0, 100);\n    if (!await updateUserMeta(req.user.id, 'redpen_sessions', updated)) return res.status(500).json({ message: 'Failed to save session' });\n    res.status(201).json({ session });\n  } catch (error) { res.status(500).json({ message: 'Failed to save session' }); }\n});\n\napp.get('/api/papers', authMiddleware, async (req, res) => {\n  try {\n    const sessionKey = String(req.query.sessionKey || '');\n    const papers = (await getUserMeta(req.user.id, 'redpen_papers')) || [];\n    res.json({ papers: (Array.isArray(papers) ? papers : []).filter(p => !sessionKey || p.sessionKey === sessionKey) });\n  } catch (error) { res.status(500).json({ message: 'Failed to load saved papers' }); }\n});\n\napp.post('/api/papers', authMiddleware, async (req, res) => {\n  try {\n    const { sessionKey, type, name, dataUrl, mimeType } = req.body || {};\n    if (!sessionKey || !['scheme','paper'].includes(type) || !dataUrl) return res.status(400).json({ message: 'sessionKey, type and dataUrl are required' });\n    const match = String(dataUrl).match(/^data:([^;]+);base64,(.+)$/);\n    if (!match) return res.status(400).json({ message: 'Invalid data URL' });\n    const buffer = Buffer.from(match[2], 'base64');\n    if (buffer.length > 50 * 1024 * 1024) return res.status(413).json({ message: 'Paper is too large (max 50MB)' });\n    const upload = await uploadUserMedia(buffer, name || `redpen-${type}`, mimeType || match[1]);\n    if (!upload.success) return res.status(502).json({ message: upload.error || 'Failed to store paper' });\n    const existing = (await getUserMeta(req.user.id, 'redpen_papers')) || [];\n    const papers = Array.isArray(existing) ? existing : [];\n    const paper = { id: `paper_${Date.now()}_${Math.random().toString(36).slice(2,8)}`, sessionKey, type, name: name || type, url: upload.url, mediaId: upload.mediaId, createdAt: new Date().toISOString() };\n    const updated = [paper, ...papers.filter(p => !(p.sessionKey === sessionKey && p.type === type))].slice(0, 200);\n    if (!await updateUserMeta(req.user.id, 'redpen_papers', updated)) return res.status(500).json({ message: 'Paper uploaded but metadata could not be saved' });\n    res.status(201).json({ paper });\n  } catch (error) { res.status(500).json({ message: 'Failed to save paper' }); }\n});\n\napp.get('/api/papers/:id/content', authMiddleware, async (req, res) => {\n  try {\n    const papers = (await getUserMeta(req.user.id, 'redpen_papers')) || [];\n    const paper = (Array.isArray(papers) ? papers : []).find(p => p.id === req.params.id);\n    if (!paper?.url) return res.status(404).json({ message: 'Paper not found' });\n    const response = await axios.get(paper.url, { responseType: 'arraybuffer', timeout: 30000 });\n    res.set('Content-Type', response.headers['content-type'] || 'application/octet-stream');\n    res.send(Buffer.from(response.data));\n  } catch (error) { res.status(500).json({ message: 'Failed to load saved paper' }); }\n});\n\n'''
if "app.get('/api/sessions'" not in s: s=s.replace(marker,block+marker)
p.write_text(s)

