s=s.replace("pdf.addImage(imageDataUrl, 'JPEG', 0, 0, naturalW, naturalH);","const imageFormat = imageDataUrl.startsWith('data:image/png') ? 'PNG' : imageDataUrl.startsWith('data:image/webp') ? 'WEBP' : 'JPEG';\n            pdf.addImage(imageDataUrl, imageFormat, 0, 0, naturalW, naturalH);")
