s=s.replace("    const wbout = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });\n    const blob = new Blob([wbout], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });\n\n    return writeFileToFolder(folder, filename, blob);","    const wbout = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });\n    const blob = new Blob([wbout], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });\n\n    if (!folder) {\n        try {\n            let binary = '';\n            const bytes = new Uint8Array(wbout);\n            for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));\n            localStorage.setItem(browserCacheKey, btoa(binary));\n        } catch (err) { console.warn('Could not cache Excel workbook locally:', err); }\n    }\n\n    return writeFileToFolder(folder, filename, blob);")
p.write_text(s)

