marker="    // Detect return from PayChangu checkout"
sync='''    // Cloud session sync and paper restoration.\n    useEffect(() => {\n        if (!user || !token) return;\n        (async () => {\n            try {\n                const local = loadSessions();\n                for (const session of local) {\n                    await fetch('/api/sessions', { method: 'POST', headers: authHeaders(), body: JSON.stringify({ session }) });\n                }\n                const res = await fetch('/api/sessions', { headers: authHeaders() });\n                if (res.ok) {\n                    const data = await res.json();\n                    const cloud = Array.isArray(data.sessions) ? data.sessions : [];\n                    const key = s => `${s.courseCode}|${s.academicYear || ''}|${s.semester || ''}|${s.sessionLabel || ''}|${s.customName || ''}`;\n                    const merged = [...cloud, ...local].filter((session, i, all) => all.findIndex(s => key(s) === key(session)) === i).slice(0, 100);\n                    saveSessions(merged);\n                    setSessionRevision(v => v + 1);\n                    if (!semesterCourse && merged[0]) setSemesterCourse(merged[0]);\n                }\n            } catch (err) { console.error('Failed to sync sessions:', err); }\n        })();\n    }, [user, token]);\n\n    useEffect(() => {\n        if (!user || !semesterCourse || !token) return;\n        const sessionKey = `${semesterCourse.courseCode}|${semesterCourse.academicYear || ''}|${semesterCourse.semester || ''}|${semesterCourse.sessionLabel || ''}|${semesterCourse.customName || ''}`;\n        (async () => {\n            try {\n                const res = await fetch(`/api/papers?sessionKey=${encodeURIComponent(sessionKey)}`, { headers: authHeaders() });\n                if (!res.ok) return;\n                const data = await res.json();\n                for (const saved of (Array.isArray(data.papers) ? data.papers : [])) {\n                    const content = await fetch(`/api/papers/${encodeURIComponent(saved.id)}/content`, { headers: authHeaders() });\n                    if (!content.ok) continue;\n                    const blob = await content.blob();\n                    const reader = new FileReader();\n                    const dataUrl = await new Promise(resolve => { reader.onload = () => resolve(reader.result); reader.readAsDataURL(blob); });\n                    if (saved.type === 'scheme' && !markingScheme) setMarkingScheme({ base64: dataUrl as string, name: saved.name });\n                    if (saved.type === 'paper' && !studentPaper) setStudentPaper({ base64: dataUrl as string, name: saved.name });\n                }\n            } catch (err) { console.error('Failed to restore saved papers:', err); }\n        })();\n    }, [user, semesterCourse?.courseCode, semesterCourse?.academicYear, semesterCourse?.semester, semesterCourse?.sessionLabel, semesterCourse?.customName]);\n\n'''
if 'Cloud session sync and paper restoration' not in s: s=s.replace(marker,sync+marker)
